def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    years_less_than_10 = []
    if v1 < 10:
        years_less_than_10.append("2019")
    if v2 < 10:
        years_less_than_10.append("2018")

    return {
        "value": years_less_than_10,
        "trace": {
            "v1": v1,
            "v2": v2,
            "threshold": 10,
            "comparison": {
                "2019": v1 < 10,
                "2018": v2 < 10
            },
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": None
            }
        }
    }
